// MIT. Exact editorial review bases inside the original submission draft.
export const REQUIREMENT_REVIEW_SCHEMA='stellar-forge.grant-required-content-review.v1';
export const REQUIREMENT_COVERAGE_SCHEMA='stellar-forge.grant-required-content-coverage.v1';
const clone=value=>JSON.parse(JSON.stringify(value));
const need=(value,message)=>{if(!value)throw new Error(message);};
const text=(value,name)=>need(typeof value==='string',name+' must be text.');
const object=(value,name)=>need(value&&typeof value==='object'&&!Array.isArray(value),name+' must be an object.');
const list=(value,name)=>need(Array.isArray(value),name+' must be a list.');
const statuses=['unreviewed','covered','needs-edit','not-applicable'];
export function reviewCanonical(value){
  if(value===null||typeof value==='string'||typeof value==='boolean')return JSON.stringify(value);
  if(typeof value==='number'){need(Number.isFinite(value),'Keep finite review values.');return JSON.stringify(value);}
  if(Array.isArray(value))return '['+value.map(reviewCanonical).join(',')+']';
  object(value,'Review value');return '{'+Object.keys(value).sort().map(key=>JSON.stringify(key)+':'+reviewCanonical(value[key])).join(',')+'}';
}
const same=(a,b)=>reviewCanonical(a)===reviewCanonical(b);
function ids(values,name,allowed=null){
  list(values,name);need(new Set(values).size===values.length,'Select each '+name+' once.');
  values.forEach(value=>{text(value,name);need(value.length>0&&(!allowed||allowed.includes(value)),'Select an original '+name+'.');});
}
function selection(value,answerIds){
  object(value,'Review selection');ids(value.answerIds,'answer identity',answerIds);ids(value.fieldIds,'field identity');
}
function decision(value){
  object(value,'Editorial decision');text(value.actor,'Reviewer');text(value.note,'Decision note');
  need(statuses.includes(value.status),'Select an editorial decision.');
}
function validateBasis(value,answerIds){
  object(value,'Complete reviewed text');selection(value.selection,answerIds);
  object(value.criteria,'Selected published criteria');
  for(const key of ['url','reviewedAt'])text(value.criteria[key],'Criteria '+key);
  ids(value.fieldOrder,'reviewed field order');need(same([...value.fieldOrder].sort(),[...value.selection.fieldIds].sort()),'Retain each reviewed field in its original output order.');
  list(value.answers,'Reviewed answers');list(value.fields,'Reviewed fields');list(value.dependencies,'Field source answers');
  ids(value.answers.map(row=>row.id),'reviewed answer identity',answerIds);
  ids(value.dependencies.map(row=>row.id),'field source answer identity',answerIds);
  need(same(value.answers.map(row=>row.id),value.selection.answerIds),'Retain the complete ordered answer selection.');
  need(same(value.fields.map(row=>row.id),value.selection.fieldIds),'Retain the complete ordered field selection.');
  for(const row of [...value.answers,...value.dependencies]){object(row,'Complete reviewed answer');text(row.text,'Reviewed answer text');}
  for(const row of value.fields){
    object(row,'Complete reviewed field');
    for(const key of ['id','label','prompt','text','sourceUrl','observedAt','characterMethod'])text(row[key],'Reviewed field '+key);
    ids(row.answerIds,'field answer identity',answerIds);
    for(const key of ['wordLimit','characterLimit'])need(row[key]===null||Number.isSafeInteger(row[key])&&row[key]>0,'Retain the original field limit.');
    need(['unspecified','characters','utf16','utf8Bytes'].includes(row.characterMethod),'Retain the original field counting rule.');
  }
  const dependencies=[...new Set(value.fields.flatMap(row=>row.answerIds))];
  need(same(dependencies,value.dependencies.map(row=>row.id)),'Retain every selected field source answer.');
  if(value.fields.length){object(value.form,'Reviewed issuer form');for(const key of ['name','url','observedAt','notes'])text(value.form[key],'Reviewed form '+key);}
  else need(value.form===null,'Canonical-only review has no issuer-field context.');
}
export function validateRequirementReviews(state,answerIds){
  for(const review of state.reviews){
    if(review.contentReview!==undefined){
      const value=review.contentReview;object(value,'Recorded required-content review');
      need(value.schema===REQUIREMENT_REVIEW_SCHEMA&&value.requirementId===review.id,'Retain the original requirement review identity.');
      decision(value);need(value.status!=='unreviewed'&&value.actor.trim()&&value.note.trim(),'Retain the named reviewer, explicit decision and supporting note.');
      text(value.reviewedAt,'Review time');need(Number.isFinite(Date.parse(value.reviewedAt)),'Retain the original review time.');
      validateBasis(value.basis,answerIds);
      need(value.status!=='covered'||value.basis.answers.length+value.basis.fields.length>0,'A covered decision needs its complete supporting text.');
    }
    if(review.contentReviewDraft!==undefined){
      decision(review.contentReviewDraft);selection(review.contentReviewDraft,answerIds);
    }
  }
  return state;
}
export function requirementReviewInput(review){
  return clone(review.contentReviewDraft||{
    actor:review.contentReview?.actor||'',status:review.status,note:review.note,
    answerIds:review.contentReview?.basis.selection.answerIds||review.answers,fieldIds:review.contentReview?.basis.selection.fieldIds||[],
  });
}
function answerRows(draft,selected,missing){
  return selected.map(id=>{const row=draft.answers.find(item=>item.id===id);if(!row){missing.push('answer:'+id);return {id,missing:true};}return {id,text:row.text};});
}
function basisOf(draft,selected,criteria,{strict=false}={}){
  const missing=[];
  const fields=selected.fieldIds.map(id=>{
    const row=draft.fields.find(item=>item.id===id);
    if(!row){missing.push('field:'+id);return {id,missing:true};}
    return clone(Object.fromEntries(['id','label','prompt','text','sourceUrl','observedAt','characterMethod','wordLimit','characterLimit','answerIds'].map(key=>[key,row[key]])));
  });
  const value={
    selection:clone(selected),criteria:clone(criteria),
    fieldOrder:draft.fields.filter(row=>selected.fieldIds.includes(row.id)).map(row=>row.id),
    answers:answerRows(draft,selected.answerIds,missing),fields,
    dependencies:answerRows(draft,[...new Set(fields.flatMap(row=>row.answerIds||[]))],missing),
    form:fields.length?clone(draft.form):null,
  };
  if(strict)need(!missing.length,'Select current answers and issuer fields before recording this review.');
  return {value,missing};
}
export function captureRequirementReview(draft,id,input,{at=new Date().toISOString(),criteria}={}){
  const previous=draft.reviews.find(row=>row.id===id);need(previous,'Select an original requirement.');
  decision(input);selection(input,draft.answers.map(row=>row.id));
  need(input.status!=='unreviewed','Choose the editorial decision to record.');
  need(input.actor.trim()&&input.note.trim(),'Name the reviewer and record the supporting location or reason.');
  need(input.status!=='covered'||input.answerIds.length+input.fieldIds.length>0,'Select the complete answer or issuer field supporting this decision.');
  need(Number.isFinite(Date.parse(at)),'Record the review time.');
  const selected={answerIds:[...input.answerIds],fieldIds:[...input.fieldIds]};
  const basis=basisOf(draft,selected,criteria,{strict:true}).value;
  const contentReview={schema:REQUIREMENT_REVIEW_SCHEMA,requirementId:id,reviewedAt:at,
    actor:input.actor,status:input.status,note:input.note,basis};
  const result={...clone(previous),status:input.status,note:input.note,answers:[...input.answerIds],contentReview};
  delete result.contentReviewDraft;return result;
}
function comparisons(before,after,kind){
  const old=new Map(before.map(row=>[row.id,row])),next=new Map(after.map(row=>[row.id,row]));
  return [...new Set([...old.keys(),...next.keys()])].map(id=>{
    const a=old.get(id)||null,b=next.get(id)||null;
    return {kind,id,before:a,after:b,status:b?.missing||!b?'removed':!a?'added':same(a,b)?'unchanged':'changed'};
  });
}
export function requirementReviewStatus(draft,id,{criteria}={}){
  const review=draft.reviews.find(row=>row.id===id);need(review,'Select an original requirement.');
  const retained=review.contentReview||null;
  if(!retained)return {id,status:'unbound',decision:review.status,actor:'',reviewedAt:null,note:review.note,
    basis:null,current:null,rows:[],changes:[],missing:[],pending:!!review.contentReviewDraft,
    meaning:'Historical editorial decision with no retained exact text basis. Record a first text-bound review.'};
  const observed=basisOf(draft,retained.basis.selection,criteria||retained.basis.criteria);
  const rows=[...comparisons(retained.basis.answers,observed.value.answers,'answer'),
    ...comparisons(retained.basis.fields,observed.value.fields,'field'),
    ...comparisons(retained.basis.dependencies,observed.value.dependencies,'field-source-answer')];
  const changes=[];
  for(const key of ['form','criteria','fieldOrder'])if(!same(retained.basis[key],observed.value[key]))changes.push({kind:key,before:clone(retained.basis[key]),after:clone(observed.value[key])});
  const beforeDecision={status:retained.status,note:retained.note,answers:retained.basis.selection.answerIds};
  const currentDecision={status:review.status,note:review.note,answers:review.answers};
  if(!same(beforeDecision,currentDecision))changes.push({kind:'decision',before:beforeDecision,after:clone(currentDecision)});
  const changed=observed.missing.length||rows.some(row=>row.status!=='unchanged')||changes.length;
  return {id,status:changed?'changed':'current',decision:retained.status,actor:retained.actor,
    reviewedAt:retained.reviewedAt,note:retained.note,basis:clone(retained.basis),current:observed.value,rows,changes,
    missing:observed.missing,pending:!!review.contentReviewDraft,
    meaning:'An editorial decision applies only to the retained complete selected text and context; it is not issuer approval.'};
}
export function requirementCoverage(draft,{outputKind='answers',criteria,includeText=true}={}){
  need(['answers','fields'].includes(outputKind),'Select the actual prepared output.');
  const reviews=draft.reviews.map(review=>{
    const current=requirementReviewStatus(draft,review.id,{criteria});
    const relevant=current.basis?.selection[outputKind==='fields'?'fieldIds':'answerIds']||[];
    const itemSet=new Set((outputKind==='fields'?draft.fields:draft.answers).map(row=>row.id));
    const supported=relevant.length>0&&relevant.every(id=>itemSet.has(id));
    const readiness=current.status==='unbound'?'unbound':current.status==='changed'?'changed':
      current.pending?'pending-decision':current.decision==='covered'&&!supported?'different-output':
      current.decision==='covered'?'reviewed':current.decision==='not-applicable'?'reviewed-not-applicable':'needs-edit';
    const row={id:review.id,...current,readiness,outputItemIds:[...relevant]};
    if(!includeText){delete row.basis;delete row.current;delete row.rows;delete row.changes;}
    return row;
  });
  return {schema:REQUIREMENT_COVERAGE_SCHEMA,outputKind,criteria:criteria?clone(criteria):null,includeText,reviews,
    attention:reviews.filter(row=>!['reviewed','reviewed-not-applicable'].includes(row.readiness)).map(row=>row.id),
    meaning:'Exact retained editorial review of selected submission text. No automatic content sufficiency, issuer acceptance or grant eligibility is asserted.'};
}
export function requirementCoverageHtml(value){
  const escape=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const pre=value=>'<pre>'+escape(typeof value==='string'?value:JSON.stringify(value,null,2))+'</pre>';
  return '<section><h2>Required content at preparation</h2><p>'+escape(value.meaning)+'</p>'+
    value.reviews.map(row=>'<section><h3>'+escape(row.id)+' · '+escape(row.readiness)+'</h3><p>'+
      escape(row.actor||'No text-bound reviewer')+' · '+escape(row.reviewedAt||'No recorded text basis')+' · '+escape(row.decision)+'</p>'+
      pre(row.note)+'<p>Selected '+escape(value.outputKind)+': '+escape(row.outputItemIds.join(', ')||'none')+'</p>'+
      (row.basis?'<details><summary>Complete reviewed text and context</summary>'+pre(row.basis)+'</details>':'')+
      (row.status==='changed'?'<details><summary>Complete current text and changes at preparation</summary>'+pre(row.current)+pre(row.changes)+'</details>':'')+
      '</section>').join('')+'</section>';
}

// MIT. Required-content review in the original saved submission editor.
import {requirementReviewInput,requirementReviewStatus,requirementCoverage} from './grant-requirement-review-core.mjs';
export function renderRequirementReviews(root,context){
  const {node,button,input,select,link,touch,render,status,getDraft,setDraft,ANSWERS,REQUIREMENTS,OFFICIAL,
    recordReview,showAnswer,showField,download}=context;
  const draft=getDraft(),criteria={url:OFFICIAL.criteria,reviewedAt:OFFICIAL.reviewedAt};
  root.append(node('h2','Required content'),node('p','Review the complete text the issuer will read. Record who reviewed each requirement, the supporting answers or actual form fields, and the decision. Later changes remain visible.'));
  const references=node('div',undefined,'row');
  references.append(link('Submission criteria',OFFICIAL.criteria),link('Budget guidance',OFFICIAL.budget),link('Official rules',OFFICIAL.rules));
  root.append(references,node('p','Criteria source reviewed '+OFFICIAL.reviewedAt+'. These are editorial decisions. The selected text and notes do not establish issuer approval.','muted'));
  const summary=node('section',undefined,'card');
  summary.append(node('h3','Review the intended output'));
  const coverageLines=[];
  const updateCoverage=()=>{for(const [kind,line]of coverageLines){const coverage=requirementCoverage(getDraft(),{outputKind:kind,criteria});line.textContent=(kind==='answers'?'Canonical answers':'Issuer form fields')+': '+(coverage.reviews.length-coverage.attention.length)+' of '+coverage.reviews.length+' requirements have a current recorded decision for that output. '+coverage.attention.length+' need attention.';}};
  for(const kind of ['answers','fields']){
    const line=node('p');line.dataset.requiredContentCoverage=kind;coverageLines.push([kind,line]);summary.append(line);
    summary.append(button('Download complete '+(kind==='answers'?'answer':'issuer-field')+' review',()=>{
      download(JSON.stringify(requirementCoverage(getDraft(),{outputKind:kind,criteria}),null,2)+'\n',
        'scf-required-content-'+kind+'.json');
      status('Downloaded the complete editorial decisions, reviewed text and current comparisons.');
    }));
  }
  updateCoverage();root.append(summary);
  for(const rule of REQUIREMENTS){
    const review=draft.reviews.find(row=>row.id===rule.id),observed=requirementReviewStatus(draft,rule.id,{criteria});
    const card=node('section',undefined,'card');card.dataset.requirementId=rule.id;card.dataset.reviewBasisState=observed.status;
    card.append(node('h3',rule.title),node('p',rule.detail));
    const state=node('p',observed.status==='unbound'?'Needs first review of exact text':
      observed.status==='changed'?'Reviewed text or context changed — review again':'Recorded review matches the selected text','issues');
    state.setAttribute('role','status');card.append(state);
    card.append(node('p','Recorded decision: '+review.status+(observed.actor?' · '+observed.actor+' · '+observed.reviewedAt:''),'muted'));
    if(observed.status==='unbound')card.append(node('p','The existing status and note remain historical. No exact text basis was recorded, so they have not been attached to the current wording.'));
    const pendingLine=node('p','An unfinished review decision is retained. Record it explicitly when ready.','muted');
    pendingLine.hidden=!observed.pending;pendingLine.setAttribute('role','status');card.append(pendingLine);
    let discardButton=null;
    const updatePending=()=>{const pending=!!review.contentReviewDraft;pendingLine.hidden=!pending;card.dataset.reviewPending=String(pending);if(discardButton)discardButton.hidden=!pending;updateCoverage();};
    const compare=node('details');compare.append(node('summary','Read complete reviewed and current text'));
    if(!observed.basis)compare.append(node('p','No previous text-bound review is available.'),node('pre',review.note,'source-text'));
    for(const row of observed.rows){
      const label=row.kind==='field'?(row.after?.label||row.before?.label||row.id):(ANSWERS.find(item=>item[0]===row.id)?.[1]||row.id);
      const section=node('section');section.append(node('h4',label+' · '+row.kind+' · '+row.status));
      section.append(node('h5','At the recorded review'),node('pre',row.before?JSON.stringify(row.before,null,2):'(not selected)','source-text'),
        node('h5','Current draft'),node('pre',row.after?JSON.stringify(row.after,null,2):'(removed)','source-text'));
      compare.append(section);
    }
    for(const change of observed.changes)compare.append(node('h4',change.kind+' changed'),
      node('h5','At the recorded review'),node('pre',JSON.stringify(change.before,null,2),'source-text'),
      node('h5','Current draft'),node('pre',JSON.stringify(change.after,null,2),'source-text'));
    if(observed.basis){const full=node('details');full.append(node('summary','Complete original basis'),node('pre',JSON.stringify(observed.basis,null,2),'source-text'));compare.append(full);}
    card.append(compare);
    const initial=requirementReviewInput(review);
    const change=(key,value)=>{review.contentReviewDraft={...requirementReviewInput(review),[key]:value};touch('Review changes are retained as unfinished work; record the decision when ready.');updatePending();};
    card.append(input('Reviewer name',initial.actor,value=>change('actor',value)).wrap,
      select('Decision to record',initial.status,[['unreviewed','Choose a decision'],['covered','Covered in selected text'],['needs-edit','Needs editing'],['not-applicable','Not applicable — explain why']],value=>change('status',value)).wrap,
      input('Supporting location and decision reason',initial.note,value=>change('note',value),{area:true}).wrap);
    const choices=node('details');choices.open=true;choices.append(node('summary','Select complete text reviewed'));
    choices.append(node('p','Select actual issuer fields to review field output. Selecting only canonical answers does not review the fields. Linked source-answer changes also require a new review of a selected field.','muted'));
    const choose=(key,id,checked)=>{
      const selected=requirementReviewInput(review)[key];
      change(key,checked?[...selected,id]:selected.filter(value=>value!==id));render();
    };
    for(const [kind,rows,key]of [
      ['answer',draft.answers,'answerIds'],['field',draft.fields,'fieldIds'],
    ]){
      choices.append(node('h4',kind==='answer'?'Canonical answers':'Actual issuer fields'));
      if(!rows.length)choices.append(node('p','No issuer fields have been recorded.'));
      for(const item of rows){
        const label=kind==='answer'?(ANSWERS.find(row=>row[0]===item.id)?.[1]||item.id):(item.label||'Unlabeled field');
        const line=node('div',undefined,'row'),wrap=node('label',undefined,'check-row'),check=node('input');
        check.type='checkbox';check.checked=initial[key].includes(item.id);check.dataset.reviewTextId=kind+':'+item.id;
        check.addEventListener('change',()=>choose(key,item.id,check.checked));
        wrap.append(check,node('span',label));line.append(wrap,button('Open '+label,()=>kind==='answer'?showAnswer(item.id):showField(item.id)));choices.append(line);
        if(check.checked){
          const detail=node('details');detail.append(node('summary','Complete current '+label));
          if(kind==='field')detail.append(node('p',item.prompt),node('p','Source answers: '+item.answerIds.join(', '),'muted'));
          detail.append(node('pre',item.text,'source-text'));choices.append(detail);
        }
      }
      for(const id of initial[key].filter(id=>!rows.some(row=>row.id===id))){
        choices.append(node('p','Selected '+kind+' was removed: '+id,'issues'),
          button('Remove missing selection '+id,()=>choose(key,id,false)));
      }
    }
    card.append(choices);
    const controls=node('div',undefined,'row');
    controls.append(button('Record review of this exact text',()=>{
      const current=getDraft(),selected=current.reviews.find(row=>row.id===rule.id);
      setDraft(recordReview(current,rule.id,requirementReviewInput(selected)));touch();render();
      status('Recorded the named review and complete text basis. The preceding decision and draft remain in Saved versions.');
    },'primary'));
    discardButton=button('Discard unfinished review edits',()=>{
      const next=context.retainVersion(getDraft(),'Before discarding unfinished requirement review');
      delete next.reviews.find(row=>row.id===rule.id).contentReviewDraft;setDraft(next);touch();render();
    });controls.append(discardButton);updatePending();
    card.append(controls,node('p','Recording keeps the current answer and field wording. It saves an editorial decision and retains the preceding full draft version.','muted'));
    root.append(card);
  }
}

import {validateRequirementReviews,captureRequirementReview} from './grant-requirement-review-core.mjs';
import {validateGrantOperatingSelection} from './grant-operating-plan-core.mjs';
import {validateProductSourceAuthoring,productSourceSelectionOf,restoreProductSourceSelection} from './grant-product-authoring-core.mjs';
import {validatePlanningUpdateState,selectPlanningRevision} from './grant-plan-update-core.mjs';
import {validateHandover,handoverSelectionOf,restoreHandoverSelection} from './grant-handover-core.mjs';
import {validatePlanSources, validatePlanningState, newPlanReview} from './grant-plan-core.mjs';
// MIT. Portable model for the existing SCF application and its local submission draft.
export const SCHEMA = 'stellar-forge.grant-submission-draft.v1';
export const ENVELOPE = 'stellar-forge.grant-submission-export.v1';
export const MAX_BYTES = 16 * 1024 * 1024;
export const ANSWERS = [
  ['project','Project and requested outcome'],
  ['need','Customer problem, need and adoption'],
  ['stellar','Why Stellar and what we contribute'],
  ['architecture','Defined architecture and operating behavior'],
  ['product','Working product and demonstrated results'],
  ['delivery','Three funded tranches and six priced deliverables'],
  ['outcomes','Threat response and outcome measurement'],
  ['capacity','Delivery capacity, payment timing and sustainability'],
  ['applicant','Applicant, experience and submission'],
];
// Later canonical headings retain the same nine saved-answer identities.
const ANSWER_HEADINGS = new Map([
  ...ANSWERS.map(([id, title]) => [title, id]),
  ["Customer problem, first payer and adoption", "need"],
  ["Why Stellar and how the product differs", "stellar"],
  ["Defined architecture and customer operation", "architecture"],
  ["Working foundation and demonstrated customer results", "product"],
  ["Threat response and measurable acceptance", "outcomes"],
  ["Capacity, payment timing and sustainability", "capacity"],
]);
export const REQUIREMENTS = [
  {id:'complete',title:'A complete answer within the form',answers:ANSWERS.map(x=>x[0]),detail:'Include the facts needed for review in the answers themselves.'},
  {id:'need',title:'Demonstrated customer need',answers:['need','product'],detail:'Explain actual use or validated need and relevant experience.'},
  {id:'integration',title:'Meaningful Stellar operation',answers:['stellar','architecture'],detail:'Describe the system and how Stellar supports its useful operation.'},
  {id:'readiness',title:'A team ready to build',answers:['applicant','capacity','delivery'],detail:'Connect relevant skills, selected infrastructure and a feasible delivery plan.'},
  {id:'budget',title:'Prospective eligible development',answers:['delivery','capacity'],detail:'Price the remaining Stellar implementation work and explain the allocation.'},
  {id:'tranches',title:'Three priced delivery tranches',answers:['delivery'],detail:'Give outcomes, timing, cost and completion measures; finish with mainnet.'},
  {id:'response',title:'Second-tranche threat response',answers:['outcomes','delivery'],detail:'Include the threat model and monitoring procedure in the second tranche.'},
  {id:'value',title:'Ecosystem contribution',answers:['stellar','product'],detail:'Explain the value and difference from existing solutions.'},
  {id:'eligibility',title:'Applicant and applicable conditions',answers:['applicant'],detail:'Review eligibility, open-source contract plans and any applicable track or funding conditions.'},
];
export const OFFICIAL = {
  reviewedAt:'2026-10-13',
  criteria:'https://stellar.gitbook.io/scf-handbook/scf-awards/build-award/submission-criteria',
  budget:'https://stellar.gitbook.io/scf-handbook/scf-awards/build-award/budget-and-deliverable-guidelines',
  rules:'https://stellar.gitbook.io/scf-handbook/scf-awards/official-rules-for-submissions',
  round:'https://communityfund.stellar.org/awards/recxrSMYwAl8vcglg',
  deadline:'2026-11-08',
};
const ids = ANSWERS.map(x=>x[0]);
const reviewIds = REQUIREMENTS.map(x=>x.id);
const clone = value => JSON.parse(JSON.stringify(value));
function need(value,message){if(!value)throw new Error(message);}
function string(value,name){need(typeof value==='string',name+' must be text.');return value;}
function list(value,name){need(Array.isArray(value),name+' must be a list.');return value;}
function unique(value,name){need(new Set(value).size===value.length,'Keep unique '+name+'.');}
function iso(value,name){need(typeof value==='string'&&Number.isFinite(Date.parse(value)),name+' needs an actual date.');}
function hash(value,size,name){need(typeof value==='string'&&new RegExp('^[a-f0-9]{'+size+'}$').test(value),'Retain the original '+name+'.');}
function limit(value,name){need(value===null||(Number.isSafeInteger(value)&&value>=1),name+' is a positive integer, or empty.');}
function webUrl(value,loopback=false){const match=value.match(/^(https?):\/\/(\[[0-9a-f:.]+\]|[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?)(?::(\d{1,5}))?(?:[/?#][^\s]*)?$/i);return !!match&&(!match[3]||Number(match[3])<=65535)&&(match[1].toLowerCase()==='https'||(loopback&&['127.0.0.1','localhost','[::1]'].includes(match[2].toLowerCase())));}
function httpsOrEmpty(value,name){string(value,name);need(!value||webUrl(value),name+' needs an HTTPS URL without credentials.');}
export function measureText(value){
  string(value,'Answer');let utf8Bytes=0;
