export const GRANT_OPERATING_REVIEW_RECEIPT_SCHEMA = 'stellar-forge.grant-operating-review-receipt.v1';
export const GRANT_OPERATING_SELECTION_SCHEMA = 'stellar-forge.grant-operating-selection.v1';
