// MIT. Review native SF47 planning editions inside the existing submission draft.
export const PLAN_SCHEMA = 'stellar-forge.sf47-planning.v1';
export const PLAN_SOURCE_SCHEMA = 'stellar-forge.grant-plan-source.v1';
